class Solution:
    def minimalKSum(self, nums: List[int], k: int) -> int:
        vals = sorted(set(nums))
        ans, prev = 0, 0
        for v in vals:
            gap = v - prev - 1
            if gap >= k:
                break
            ans += gap * (prev + v) // 2
            k -= gap
            prev = v
        ans += k * (2 * prev + k + 1) // 2
        return ans

