class Solution {
    public long minimalKSum(int[] nums, int k) {
        Arrays.sort(nums);
        long ans = 0, prev = 0;
        int i = 0;
        while (i < nums.length && k > 0) {
            long gap = nums[i] - prev - 1;
            if (gap > 0) {
                long take = Math.min(gap, k);
                ans += take * (prev + 1 + prev + take) / 2;
                k -= take;
                prev += take;
            }
            prev = Math.max(prev, nums[i]);
            i++;
        }
        ans += (long) k * (prev + 1 + prev + k) / 2;
        return ans;
    }
}

