class Solution {
    public long minimalKSum(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i+1] = pref[i] + nums[i];
        long lo = k, hi = (long) k + n;
        while (lo < hi) {
            long mid = (lo + hi) >>> 1;
            int i = upperBound(nums, (int) mid);
            long f = mid * (mid + 1) / 2 - pref[i];
            if (f >= k) hi = mid; else lo = mid + 1;
        }
        int i = upperBound(nums, (int) lo);
        return lo * (lo + 1) / 2 - pref[i];
    }
    private int upperBound(int[] a, int x) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a[m] <= x) lo = m + 1; else hi = m; }
        return lo;
    }
}

