var minimalKSum = function(nums, k) {
    const vals = [...new Set(nums)].sort((a,b)=>a-b);
    const pref = [0];
    for (const v of vals) pref.push(pref[pref.length-1] + v);
    const f = m => {
        let lo = 0, hi = vals.length;
        while (lo < hi) { const md = (lo+hi)>>1; if (vals[md] <= m) lo = md+1; else hi = md; }
        return m*(m+1)/2 - pref[lo];
    };
    let lo = k, hi = k + vals.length;
    while (lo < hi) { const mid = Math.floor((lo+hi)/2); if (f(mid) >= k) hi = mid; else lo = mid+1; }
    return f(lo);
};
